<!doctype html>
<html>
    <head>
        <meta charset="utf-8">
        <style>
            @import url('http://fonts.googleapis.com/css2?family=Roboto:wght@100;300;400;500;700;900&display=swap'); body {
                font-family: 'Roboto', sans-serif;
            }

            .f-left {
                float: left;
            }

            .f-right {
                float: right;
            }

            .t-right {
                text-align: right;
            }

            .t-center {
                text-align: center;
            }

            .t-left {
                text-align: left;
            }

            .logo-h {
                width: 80px;
            }

            .logo-m {
                width: 160px;
            }

            .border {
                border: 1px solid #000;
                border-radius: 10px;
            }

            .full-width {
                padding: 15px;
                overflow: hidden;
            }

            .report p strong {
                font-size: 20px;
            }

            .report p {
                color: #000;
                margin: 0px;
                padding-top: 8px;
                font-size: 13px;
            }

            .report p a {
                color: #000;
            }

            .head-block {
                overflow: hidden;
                margin-bottom: 15px;
            }

            .full-width h4 {
                margin: 0px;
                color: #000;
                font-size: 20px;
            }

            .border-bottom {
                border-bottom: 1px solid #0000006e;
                overflow: hidden;
                padding-top: 15px;
                margin-bottom: 15px;
            }

            .vehicle-information .information-d {
                padding-top: 5px;
            }

            .vehicle-information ul {
                margin-top: 0px;
                padding-left: 15px;
            }

            .vehicle-information ul li {
                width: 45%;
                float: left;
                color: #000;
                font-size: 16px;
                display: block;
                padding: 12px 0px;
                position: relative;
                padding-left: 25px;
            }

            img.icon-logo {
                width: 25px;
                position: absolute;
                left: -2px;
                top: 10px;
            }

            .information-detail h3 {
                margin: 0px;
                color: #000;
                font-weight: 300;
                font-size: 22px;
            }

            .information-detail h5 {
                margin: 0px;
                color: #000;
                font-weight: 300;
                font-size: 25px;
            }

            .information-detail h1 {
                font-size: 28px;
                font-weight: bold;
                color: #000;
                margin: 0px;
            }

            .information-detail h1 sub {
                font-size: 20px;
                font-weight: 300;
            }

            .w-full {
                width: 100%;
            }

            .bottom-text {
                width: 100%;
                overflow: hidden;
                line-height: 15px;
            }

            .vehicle-information {
                overflow: hidden;
            }
        </style>
    </head>
    <body style="width:800px;margin:30px auto;">
        <div class="report" style="border: 1px solid #000; padding: 10px; margin:40px 0px;float:left;">
            <div class="head-block">
                <div class="report-header-left f-left" style="width:50%;">
                    <img src="data:image/png;base64,
" class="logo-m"/>
                </div>
                <div class="report-header-right f-right t-right" style="width:50%;">
                    <p>
                        <strong style="font-size:27px;">{{BNAME}}</strong>
                    </p>
                    <p>{{BADDRESS}}, {{BCITY}}, {{BSTATE}} {{BCODE}}</p>
                    <p>{{BPHONE}}</p>
                </div>
            </div>
            <div class="border full-width">
                <div class="report-header-left f-left" style="width:50%;">
                    <h4 style="font-size:27px;">{{YEAR}} {{MAKE}} {{MODEL}}</h4>
                    <p>
                        <span class="vin">VIN: {{VIN}}</span>
                        <span class="stock">Stock #: {{STOCK}}</span>
                    </p>
                    <p>{{ODOMETER}} {{KM_MILES}}</p>
                </div>
                <div class="report-header-right f-right t-right information-detail" style="width:50%;">
                    <h3>VEHICLE PRICE</h3>
                    <p>
                        <strong style="font-size:30px;padding-right: 15px;">${{PRICE}}</strong>
                        
                    </p>
                    <p>+ Taxes and Licensing</p>
                </div>
				
				<div class="descp" style="margin:10px 0px 0px; float:left;width:100%;padding:0px;">
				 <p style="padding:0px;"><strong>Vehicle Description</strong></p>
				<p style="padding:0px;"> {{DESCRIPTION_1000}} </p>
				</div>
                <div class="border-bottom" style="width:100%;"></div>
                <div class="vehicle-information">
                    <p>
                        <strong>Vehicle Information</strong>
                    </p>
                    <ul>
                        <li>
                            <img src="data:image/png;base64," class="icon-logo"/>
                            Body Type: <strong>{{BODY}}</strong>
                        </li>
                        <li>
                            <img src="data:image/png;base64," class="icon-logo"/>
                            Doors: <strong>{{DOOR}}</strong>
                        </li>
                        <li>
                            <img src="data:image/png;base64," class="icon-logo"/>
                            Engine: <strong>{{ENGINE}}</strong>
                        </li>
                        <li>
                            <img src="data:image/png;base64," class="icon-logo"/>
                            Cylinder: <strong>{{CYLINDER}}</strong>
                        </li>
                        <li>
                            <img src="data:image/png;base64," class="icon-logo"/>
                            Transmission: <strong>{{TRANSMISSION}}</strong>
                        </li>
                        <li>
                            <img src="data:image/png;base64," class="icon-logo"/>
                            Drivetrain: <strong>{{DRIVETRAIN}}</strong>
                        </li>
                        <li>
                            <img src="data:image/png;base64," class="icon-logo"/>
                            Passengers: <strong>{{PASSENGERS}}</strong>
                        </li>
                        <li>
                            <img src="data:image/png;base64," class="icon-logo"/>
                            Exterior Colour: <strong>{{EXTERIOR_COLOR}}</strong>
                        </li>
                        <li>
                            <img src="data:image/png;base64," class="icon-logo"/>
                            Interior Colour: <strong>{{INTERIOR_COLOR}}</strong>
                        </li>
                    </ul>
                </div>
                <!--<div class="vehicle-information">
                <p style="padding-top: 15px;"><strong>Vehicle Description</strong></p>
                <p>{{DESCRIPTION}}</p>                
            </div> -->
                <div class="border-bottom" style="width:100%;"></div>
                <div class="information-detail">
                    <p style="padding-top: 0px;font-size: 18px;padding-bottom:8px;">
                        <strong>Fuel Economy</strong>
                    </p>
                    <div class="report-header-left f-left t-center" style="width:30%;padding: 30px 10px;">
                        <h5>CITY</h5>
                        <h1>{{FUEL_CITY}}</h1>
                        <p>
                            <strong>L/100 {{KM_MILES}} </strong>
                        </p>
                    </div>
                    <div class="report-header-left f-left t-center" style="width:30%;padding: 10px 10px;">
                        <img style="width: 85px;position: relative;top: 15px;" src="data:image/png;base64," class="logo-h"/>
                    </div>
                    <div class="report-header-left f-left t-center" style="width:30%;padding: 30px 10px;">
                        <h5>HIGHWAY</h5>
                        <h1>{{FUEL_HWY}}</h1>
                        <p>
                            <strong>L/100 {{KM_MILES}}</strong>
                        </p>
                    </div>
                </div>
                <div class="border-bottom" style="width:100%;"></div>
                <div class="information-detail">
                    <div class="report-header-left f-left t-center" style="width:20%;padding: 25px 10px;">
                        <p style="padding-top: 0px;font-size: 18px;padding-bottom:8px;">SCAN ME!</p>
                        {{QR}}
                
                    </div>
                    <div class="report-header-left f-left t-center" style="width:55%;padding: 75px 10px 25px 10px;">
                        <h3 style="font-weight: 700;">{{BNAME}}</h3>
                        <p>{{BADDRESS}}, {{BCITY}}, {{BSTATE}} {{BCODE}}</p>
                        <h3 style="font-weight: 700;padding-top: 8px;">{{BPHONE}} </h3>
                    </div>
                    <div class="bottom-text t-center">
                        <p style="font-size:9px;">*Prices for this vehicle may not include charges such as License;
                        Registration Fees; Local Taxes; Finance Charges; or Delivery Fees. Every reasonable effort is
                        made to ensure the accuracy of the information listed above. Vehicle pricing, incentives,
                        options (including standard equipment), and technical specifications listed may not match the
                        exact vehicle displayed. Please confirm with a sales representative the accuracy of this
                        information.</p>
                        <!---<p style="font-size:14px; margin:15px 0px 0px;">*Prices for this vehicle may not include charges such as License;</p>--->
                    </div>
                </div>
            </div>
        </div>
    </body>
</html>

